const std = @import("std");

pub fn main() !void {
    var matrix = [_][3]i32{
        [_]i32{ 1, 2, 3 },
        [_]i32{ 4, 5, 6 },
        [_]i32{ 7, 8, 9 },
    };

    std.debug.print("Original:\n", .{});
    for (matrix) |row| {
        for (row) |val| std.debug.print("{} ", .{val});
        std.debug.print("\n", .{});
    }

    var transposed: [3][3]i32 = undefined;
    for (0..3) |i| {
        for (0..3) |j| {
            transposed[i][j] = matrix[j][i];
        }
    }

    std.debug.print("Transposed:\n", .{});
    for (transposed) |row| {
        for (row) |val| std.debug.print("{} ", .{val});
        std.debug.print("\n", .{});
    }
}

